import { isEmpty } from 'lodash-es';
import React from 'react';
import { isElement } from 'react-is';

import { ChartToolbar } from '../../core/slots/toolbar/ChartToolbar.js';
import { DownloadData } from '../../core/slots/toolbar/DownloadData.js';
import { ChartToolbarProps } from '../../core/types/toolbar.js';
import { CategoryAxis } from '../slots/CategoryAxis.js';
import { Legend } from '../slots/Legend.js';
import {
  Threshold,
  CategoricalBarChartThresholdProps,
} from '../slots/Threshold.js';
import { Tooltip } from '../slots/Tooltip.js';
import { ValueAxis } from '../slots/ValueAxis.js';
import {
  CategoricalBarChartValueAxisProps,
  CategoricalBarChartTooltipProps,
  CategoricalBarChartToolbarConfiguration,
  CategoricalBarChartSlots,
  CategoricalBarChartLegendProps,
  CategoricalBarChartCategoryAxisProps,
} from '../types/categorical-bar-chart.js';

/**
 * Generate chart config based on slots
 * @param children - CharInteraction children
 * @returns ChartInteraction slot config
 */
const iterateChartToolbarSlots = (
  children: React.ReactNode,
): CategoricalBarChartToolbarConfiguration => {
  let slots = {};

  React.Children.forEach(children, (childInteractions) => {
    if (isElement(childInteractions)) {
      switch (childInteractions.type) {
        case DownloadData:
          slots = { ...slots, downloadData: { enabled: true } };
          break;
      }
    }
  });

  return slots;
};

export const iterateSlots = (children: React.ReactNode) => {
  let slots: CategoricalBarChartSlots = {
    legend: {},
    tooltip: {},
    valueAxis: {},
    categoryAxis: {},
    thresholds: [],
    toolbar: {},
  };

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case Legend: {
          const legend = child.props as CategoricalBarChartLegendProps;

          slots = {
            ...slots,
            legend,
          };
          break;
        }
        case CategoryAxis: {
          const categoryAxis =
            child.props as CategoricalBarChartCategoryAxisProps;
          slots = {
            ...slots,
            categoryAxis,
          };
          break;
        }
        case ValueAxis: {
          const valueAxis = child.props as CategoricalBarChartValueAxisProps;

          slots = {
            ...slots,
            valueAxis,
          };
          break;
        }
        case Tooltip: {
          const tooltip = child.props as CategoricalBarChartTooltipProps;
          slots = {
            ...slots,
            tooltip,
          };
          break;
        }
        case Threshold: {
          const thresholdProps =
            child.props as CategoricalBarChartThresholdProps;

          slots.thresholds.push(thresholdProps);
          break;
        }

        case ChartToolbar: {
          const { children, ...toolbarProps } =
            child.props as React.PropsWithChildren<ChartToolbarProps>;

          const toolbarSlots = iterateChartToolbarSlots(children);

          const toolbar = isEmpty(toolbarSlots)
            ? {}
            : { ...toolbarProps, ...toolbarSlots };

          slots = { ...slots, toolbar };

          break;
        }
      }
    }
  });

  return slots;
};
